firewall_preview.ruleset:
table inet itso {
  chain input {
    type filter hook input priority 0; policy drop;
    iif lo accept
    ct state established,related accept
    icmp type echo-request limit rate 10/second accept
    tcp dport 22 ip saddr 10.10.0.0/16 accept comment "SSH chỉ từ mạng nội bộ"
    tcp dport { 80, 443 } accept comment "Web"
    tcp dport 8443 ip saddr 10.10.0.0/16 accept comment "Admin Panel"
  }
}

